func (this *Hollaex) ParseOrder(order any, optionalArgs ...any) any {
	//
	// createOrder, fetchOpenOrder, fetchOpenOrders
	//
	//     {
	//          "id":"10644b7e-3c90-4ba9-bc3b-188f3a4e9cfd",
	//          "created_by":140093,
	//          "exchange_id":22,
	//          "side":"buy",
	//          "symbol":"doge-usdt",
	//          "type":"limit",
	//          "price":0.05,
	//          "size":10,
	//          "stop":null,
	//          "filled":0,
	//          "status":"canceled",
	//          "fee":0,
	//          "fee_coin":"doge",
	//          "meta": {                 // optional field only returned for postOnly orders
	//              "post_only":true
	//          },
	//          "fee_structure": {
	//              "maker":0.1,
	//              "taker":0.1
	//          },
	//          "created_at":"2022-05-31T08:14:14.747Z",
	//          "updated_at":"2022-05-31T08:14:23.727Z"
	//      }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(order, "symbol")
	var symbol any = this.SafeSymbol(marketId, market, "-")
	var id any = this.SafeString(order, "id")
	var timestamp any = this.Parse8601(this.SafeString(order, "created_at"))
	var typeVar any = this.SafeString(order, "type")
	var side any = this.SafeString(order, "side")
	var price any = this.SafeString(order, "price")
	var amount any = this.SafeString(order, "size")
	var filled any = this.SafeString(order, "filled")
	var status any = this.ParseOrderStatus(this.SafeString(order, "status"))
	var meta any = this.SafeValue(order, "meta", map[string]any{})
	var postOnly any = this.SafeBool(meta, "post_only", false)
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           postOnly,
		"side":               side,
		"price":              price,
		"triggerPrice":       this.SafeString(order, "stop"),
		"amount":             amount,
		"filled":             filled,
		"remaining":          nil,
		"cost":               nil,
		"trades":             nil,
		"fee":                nil,
		"info":               order,
		"average":            nil,
	}, market)
}

